=== IdentityRegistry
     1	package pousada;
     2	
     3	import java.util.List;
     4	
     5	/** Único lugar que conhece os tipos de identificação aceitos. */
     6	public class IdentityRegistry {
     7	    private final List<IdentityType> types = List.of(CpfIdentity.TYPE, CnpjIdentity.TYPE, PassportIdentity.TYPE);
     8	
     9	    /** Todos os campos de identificação que aparecem no JSON, na ordem de cadastro. */
    10	    public List<String> allKeys() {
    11	        return types.stream().flatMap(t -> t.keys().stream()).toList();
    12	    }
    13	
    14	    /** Exige exatamente um tipo de identificação, com todos os campos dele. */
    15	    public GuestIdentity parse(RequestBody body) {
    16	        List<IdentityType> used = types.stream()
    17	                .filter(t -> t.keys().stream().anyMatch(body::has))
    18	                .toList();
    19	        if (used.size() != 1) {
    20	            throw ApiException.invalidRequest(
    21	                    "Informe a identificação de um único jeito: " + describeOptions());
    22	        }
    23	        return used.get(0).parse(body);
    24	    }
    25	
    26	    private String describeOptions() {
    27	        return String.join(" | ", types.stream().map(t -> String.join("+", t.keys())).toList());
    28	    }
    29	}
