     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	
     7	/**
     8	 * Documento emitido para a reserva. A sequência do texto é a mesma para todos; cada tipo de
     9	 * documento muda só o título, o idioma, as linhas do hóspede e o fechamento.
    10	 */
    11	public abstract class ReservationDocument {
    12	    protected final DocumentData data;
    13	    private final GuestIdentity identity;
    14	
    15	    protected ReservationDocument(DocumentData data, GuestIdentity identity) {
    16	        this.data = data;
    17	        this.identity = identity;
    18	    }
    19	
    20	    protected abstract String title();
    21	
    22	    protected abstract DocumentLabels labels();
    23	
    24	    protected abstract List<String> guestLines();
    25	
    26	    protected List<String> closingLines() { return List.of(); }
    27	
    28	    public final String text() {
    29	        DocumentLabels l = labels();
    30	        Quote quote = data.quote();
    31	        List<String> lines = new ArrayList<>();
    32	        lines.add(title() + " " + l.number() + " " + data.reservationId());
    33	        lines.addAll(guestLines());
    34	        lines.add(l.room() + ": " + data.roomNumber() + " (" + data.roomType() + ")");
    35	        lines.add(l.checkIn() + ": " + l.date().format(data.checkIn())
    36	                + " | " + l.checkOut() + ": " + l.date().format(data.checkOut())
    37	                + " | " + quote.nights() + " " + (quote.nights() == 1 ? l.nightOne() : l.nightMany()));
    38	        lines.add(l.subtotal() + ": " + money(quote.subtotal()));
    39	        if (quote.discount().signum() > 0) {
    40	            lines.add(l.discount() + ": " + money(quote.discount()));
    41	        }
    42	        lines.add(l.total() + ": " + money(quote.total()));
    43	        lines.addAll(closingLines());
    44	        return String.join("\n", lines);
    45	    }
    46	
    47	    protected final String money(BigDecimal value) {
    48	        return labels().money().apply(value);
    49	    }
    50	
    51	    public final String titleText() { return title(); }
    52	
    53	    public final DocumentData data() { return data; }
    54	
    55	    public final GuestIdentity identity() { return identity; }
    56	}
