     1	package pousada;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	
     7	import java.time.LocalDate;
     8	import java.time.format.DateTimeParseException;
     9	
    10	public class RequestBody {
    11	    private static final ObjectMapper MAPPER = new ObjectMapper();
    12	    private final JsonNode node;
    13	
    14	    private RequestBody(JsonNode node) { this.node = node; }
    15	
    16	    public static RequestBody parse(String json) {
    17	        try {
    18	            JsonNode node = MAPPER.readTree(json == null ? "" : json);
    19	            if (node == null || !node.isObject()) {
    20	                throw ApiException.invalidRequest("O corpo deve ser um objeto JSON");
    21	            }
    22	            return new RequestBody(node);
    23	        } catch (JsonProcessingException e) {
    24	            throw ApiException.invalidRequest("O corpo não é um JSON válido");
    25	        }
    26	    }
    27	
    28	    /** O campo veio com algum valor (texto em branco conta como ausente). */
    29	    public boolean has(String key) {
    30	        JsonNode value = node.get(key);
    31	        return value != null && !value.isNull() && !(value.isTextual() && value.asText().isBlank());
    32	    }
    33	
    34	    public String text(String key) {
    35	        if (!has(key)) throw ApiException.invalidRequest("Campo obrigatório: " + key);
    36	        JsonNode value = node.get(key);
    37	        if (!value.isTextual()) throw ApiException.invalidRequest("O campo " + key + " deve ser texto");
    38	        return value.asText().trim();
    39	    }
    40	
    41	    public int integer(String key) {
    42	        if (!has(key)) throw ApiException.invalidRequest("Campo obrigatório: " + key);
    43	        JsonNode value = node.get(key);
    44	        if (!value.isIntegralNumber() || !value.canConvertToInt()) {
    45	            throw ApiException.invalidRequest("O campo " + key + " deve ser um número inteiro");
    46	        }
    47	        return value.asInt();
    48	    }
    49	
    50	    public LocalDate date(String key) {
    51	        try {
    52	            return LocalDate.parse(text(key));
    53	        } catch (DateTimeParseException e) {
    54	            throw ApiException.invalidRequest("O campo " + key + " deve ter o formato 2027-07-10");
    55	        }
    56	    }
    57	
    58	    public <E extends Enum<E>> E enumeration(String key, Class<E> type) {
    59	        String value = text(key);
    60	        try {
    61	            return Enum.valueOf(type, value);
    62	        } catch (IllegalArgumentException e) {
    63	            throw ApiException.invalidRequest("Valor inválido para " + key + ": " + value);
    64	        }
    65	    }
    66	}
