     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public class Reservation {
     7	    private final int id;
     8	    private final Room room;
     9	    private final String guestName;
    10	    private final String guestEmail;
    11	    private final GuestIdentity identity;
    12	    private final LocalDate checkIn;
    13	    private final LocalDate checkOut;
    14	    private final int guests;
    15	    private final RatePlan ratePlan;
    16	    private final Quote quote;
    17	    private Status status = Status.PENDING;
    18	    private BigDecimal amountPaid = Money.ZERO;
    19	    private BigDecimal refund;
    20	
    21	    public Reservation(int id, Room room, String guestName, String guestEmail, GuestIdentity identity,
    22	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    23	        this.id = id;
    24	        this.room = room;
    25	        this.guestName = guestName;
    26	        this.guestEmail = guestEmail;
    27	        this.identity = identity;
    28	        this.checkIn = checkIn;
    29	        this.checkOut = checkOut;
    30	        this.guests = guests;
    31	        this.ratePlan = ratePlan;
    32	        this.quote = Quote.of(room, checkIn, checkOut, ratePlan);
    33	    }
    34	
    35	    public synchronized void confirm() {
    36	        require("confirmar", Status.PENDING);
    37	        amountPaid = quote.total();
    38	        status = Status.CONFIRMED;
    39	    }
    40	
    41	    public synchronized void checkIn() {
    42	        require("fazer check-in", Status.CONFIRMED);
    43	        status = Status.CHECKED_IN;
    44	    }
    45	
    46	    public synchronized void checkOut() {
    47	        require("fazer check-out", Status.CHECKED_IN);
    48	        status = Status.CHECKED_OUT;
    49	    }
    50	
    51	    public synchronized void cancel() {
    52	        require("cancelar", Status.PENDING, Status.CONFIRMED);
    53	        refund = ratePlan.refundFor(amountPaid);
    54	        status = Status.CANCELLED;
    55	    }
    56	
    57	    private void require(String operation, Status... allowed) {
    58	        for (Status s : allowed) {
    59	            if (status == s) return;
    60	        }
    61	        throw ApiException.operationNotAllowed(
    62	                "Não é possível " + operation + " uma reserva com status " + status);
    63	    }
    64	
    65	    /** Documento da reserva; só existe para reserva paga. */
    66	    public synchronized ReservationDocument document() {
    67	        if (!status.isPaid()) {
    68	            throw ApiException.operationNotAllowed(
    69	                    "Só existe documento para reserva paga; status atual: " + status);
    70	        }
    71	        return identity.issue(new DocumentData(id, guestName, room.number(), room.type(), checkIn, checkOut, quote));
    72	    }
    73	
    74	    public synchronized boolean occupies(LocalDate night) {
    75	        return status.isPaid() && !night.isBefore(checkIn) && night.isBefore(checkOut);
    76	    }
    77	
    78	    public boolean overlaps(LocalDate in, LocalDate out) {
    79	        return getStatus().holdsRoom() && in.isBefore(checkOut) && checkIn.isBefore(out);
    80	    }
    81	
    82	    /** O que ficou com a pousada: pago menos devolvido. */
    83	    public synchronized BigDecimal retained() {
    84	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    85	    }
    86	
    87	    public int id() { return id; }
    88	    public Room room() { return room; }
    89	    public String guestName() { return guestName; }
    90	    public String guestEmail() { return guestEmail; }
    91	    public GuestIdentity identity() { return identity; }
    92	    public LocalDate checkInDate() { return checkIn; }
    93	    public LocalDate checkOutDate() { return checkOut; }
    94	    public int guests() { return guests; }
    95	    public RatePlan ratePlan() { return ratePlan; }
    96	    public Quote quote() { return quote; }
    97	    public synchronized Status getStatus() { return status; }
    98	    public synchronized BigDecimal amountPaid() { return amountPaid; }
    99	    public synchronized BigDecimal refund() { return refund; }
   100	}

