    35	    public synchronized void confirm() {
    36	        require("confirmar", Status.PENDING);
    37	        amountPaid = quote.total();
    38	        status = Status.CONFIRMED;
    39	    }
    40	
    41	    public synchronized void checkIn() {
    42	        require("fazer check-in", Status.CONFIRMED);
    43	        status = Status.CHECKED_IN;
    44	    }
    45	
