     8	
     9	public class ReservationService {
    10	    private final RoomCatalog rooms;
    11	    private final Outbox outbox;
    12	    private final TreeMap<Integer, Reservation> reservations = new TreeMap<>();
    13	
    14	    public ReservationService(RoomCatalog rooms, Outbox outbox) {
    15	        this.rooms = rooms;
    16	        this.outbox = outbox;
    17	    }
    18	
    19	    public synchronized Reservation create(NewReservation request) {
    20	        Room room = rooms.find(request.roomNumber())
    21	                .orElseThrow(() -> ApiException.roomNotFound(request.roomNumber()));
    22	        if (request.guests() > room.capacity()) {
    23	            throw ApiException.capacityExceeded(room.capacity());
    24	        }
    25	        boolean taken = reservations.values().stream().anyMatch(r ->
    26	                r.room().equals(room) && r.overlaps(request.checkIn(), request.checkOut()));
    27	        if (taken) {
    28	            throw ApiException.roomUnavailable(room.number());
    29	        }
    30	        Reservation reservation = new Reservation(reservations.size() + 1, room, request.guestName(),
    31	                request.guestEmail(), request.identity(), request.checkIn(), request.checkOut(),
    32	                request.guests(), request.ratePlan());
    33	        reservations.put(reservation.id(), reservation);
    34	        return reservation;
    35	    }
    36	
    37	    public synchronized Reservation find(String id) {
    38	        try {
    39	            Reservation reservation = reservations.get(Integer.parseInt(id));
    40	            if (reservation != null) return reservation;
    41	        } catch (NumberFormatException ignored) {
    42	            // id que não é número não existe
    43	        }
    44	        throw ApiException.reservationNotFound(id);
    45	    }
    46	
    47	    public synchronized Reservation confirm(String id) {
    48	        Reservation reservation = find(id);
    49	        reservation.confirm();
    50	        outbox.sendEmail(reservation.guestEmail(), ConfirmationEmail.SUBJECT,
    51	                ConfirmationEmail.body(reservation.guestName(), reservation.document()));
    52	        return reservation;
    53	    }
    54	
    55	    public synchronized Reservation cancel(String id) {
    56	        Reservation reservation = find(id);
    57	        reservation.cancel();
    58	        return reservation;
    59	    }
    60	
    61	    public synchronized Reservation checkIn(String id) {
    62	        Reservation reservation = find(id);
    63	        reservation.checkIn();
    64	        return reservation;
    65	    }
    66	
    67	    public synchronized ReservationDocument checkOut(String id) {
    68	        Reservation reservation = find(id);
    69	        reservation.checkOut();
    70	        return reservation.document();
    71	    }
    72	
    73	    public synchronized ReservationDocument document(String id) {
    74	        return find(id).document();
    75	    }
    76	
    77	    public synchronized List<Reservation> occupying(LocalDate night) {
    78	        return reservations.values().stream().filter(r -> r.occupies(night)).toList();
    79	    }
    80	
    81	    /** Reservas que começam no mês e deixaram dinheiro com a pousada. */
    82	    public synchronized List<Reservation> retainedStartingIn(YearMonth month) {
    83	        return new ArrayList<>(reservations.values().stream()
    84	                .filter(r -> YearMonth.from(r.checkInDate()).equals(month))
    85	                .filter(r -> r.retained().signum() > 0)
    86	                .toList());
    87	    }
    88	}
