     8	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    12	        BigDecimal subtotal = Money.ZERO;
    13	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    14	            subtotal = subtotal.add(nightPrice(room, night));
    15	        }
    16	        BigDecimal discount = plan.discountOn(subtotal);
    17	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    18	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    19	    }
