    21	    private static BigDecimal nightPrice(Room room, LocalDate night) {
    22	        BigDecimal rate = room.nightlyRate();
    23	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    24	    }
