    30	        Reservation reservation = new Reservation(reservations.size() + 1, room, request.guestName(),
    31	                request.guestEmail(), request.identity(), request.checkIn(), request.checkOut(),
    32	                request.guests(), request.ratePlan());
    33	        reservations.put(reservation.id(), reservation);
    34	        return reservation;
    35	    }
